    public class EmrAbbrevModule : BaseModuleERP
    {
        private EmrAbbrevEntities _entity;
        private MEEmrAbbrevsController _abbrevCtrl;
        protected RichEditDocumentServer server;

        public EmrAbbrevModule()
        {
            Name = "EmrAbbrev";
            CurrentModuleEntity = new EmrAbbrevEntities();
            CurrentModuleEntity.Module = this;
            InitializeModule();
            _entity = CurrentModuleEntity as EmrAbbrevEntities;
            _abbrevCtrl = new MEEmrAbbrevsController();
            _entity.MEEmrAbbrevList.Invalidate(BOSApp.CurrentUsersInfo.FK_HREmployeeID);
            server = new RichEditDocumentServer();
        }
        public override void InvalidateAfterSearch(object sender, string strEventName)
        {
            base.InvalidateAfterSearch(sender, strEventName);
        }
        internal void DeleteAbbrevFromList()
        {
            _entity.MEEmrAbbrevList.RemoveSelectedRowObjectFromList();
        }

        internal void AddSharedAbbrevList(List<MEEmrAbbrevsInfo> list)
        {
            var msg = string.Empty;
            foreach (var item in list)
            {
                if (_entity.MEEmrAbbrevList.Any(o => o.MEEmrAbbrevNo == item.MEEmrAbbrevNo))
                {
                    msg += item.MEEmrAbbrevNo + "; ";
                }
                else
                {
                    item.MEEmrAbbrevID = 0;
                    _entity.MEEmrAbbrevList.Add(item);
                }
            }
            _entity.MEEmrAbbrevList.GridControl.RefreshDataSource();
            _entity.MEEmrAbbrevList.GridControl.Refresh();
            if (!string.IsNullOrEmpty(msg))
                MessageBox.Show("Các mã tắt sau đã tồn tại: " + msg, "Trùng mã tắt", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }

        internal void InvalidateSharedAbbrevList()
        {
            var ds = _abbrevCtrl.GetShared(BOSApp.CurrentUsersInfo.FK_HREmployeeID);
            _entity.MEEmrAbbrevSharedList.Invalidate(ds);
        }

        public void ActionInvalidateList()
        {
            _entity.MEEmrAbbrevList.Invalidate(BOSApp.CurrentUsersInfo.FK_HREmployeeID);
            _entity.MEEmrAbbrevList.GridControl.RefreshDataSource();
            _entity.MEEmrAbbrevList.GridControl.Refresh();
        }
        public void ActionSaveList()
        {
            _entity.MEEmrAbbrevList.EndCurrentEdit();
            var groups = _entity.MEEmrAbbrevList.GroupBy(i => i.MEEmrAbbrevNo).Select(g => new { Count = g.Count(), No = g.Key });
            foreach (var item in groups)
            {
                if (item.Count > 1)
                {
                    MessageBox.Show("Mã tắt trùng: " + item.No, "Trùng mã tắt. Không thể lưu", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }
            }
            foreach (var item in _entity.MEEmrAbbrevList)
            {
                item.FK_HREmployeeID = BOSApp.CurrentUsersInfo.FK_HREmployeeID;
                if (!item.MEEmrAbbrevRichText)
                {
                    item.MEEmrAbbrevContent = FormatRichEditDisplayText(item.MEEmrAbbrevContent);
                }
            }

            try
            {
                BOSLib.BOSProgressBar.Start("Đang lưu dữ liệu");
                _entity.MEEmrAbbrevList.SaveItemObjects();
            }
            catch (Exception)
            {

                throw;
            }
            finally
            {
                BOSLib.BOSProgressBar.Close();
            }
            InvalidateSharedAbbrevList();
            var emrModule = BOSApp.OpenModules["MEEmr"];
            if (emrModule != null)
            {
                ((BOSERP.Modules.MEEmr.MEEmrModule)emrModule).LoadUserAbbrevs();
            }
        }

        public void CreateFromShared()
        {
            var gui = new guiAbbrevSelection();
            gui.StartPosition = FormStartPosition.CenterParent;
            gui.Module = this;
            if (gui.ShowDialog() == DialogResult.OK)
            {

            }
        }

        internal string FormatRichEditDisplayText(string text)
        {
            if (!string.IsNullOrEmpty(text))
            {
                if (text.StartsWith("{\\rtf1"))
                {
                    server.RtfText = text;
                    return server.Text;
                }
                return text;
            }
            return string.Empty;
        }
    }
    #endregion
}